// A 39 s app-concept reel ("what if your saves came back when you need them"): a post
// is liked and saved, the save is lost in the collection, and a save reminder brings it back. Flat UI on a pale
// canvas, a camera that pushes in and whips between details with heavy motion blur, word-by-word type on dark
// gradients, hand-written ink notes, letterbox bars that open and close with the shots.
//
// Timing is the reference's, measured frame by frame at 30 fps (each shot's `from` below and the frames inside
// the shots are reference frames). The reference reel (not committed) goes in reference/reel.mp4.
//
// Render from the kinetograph-ui root:
//   node ../kinetograph/packages/cli/dist/cli.js strip templates/save-reel/index.tsx -n 12 -o templates/save-reel/out/strip.png
//   node ../kinetograph/packages/cli/dist/cli.js render templates/save-reel/index.tsx -o templates/save-reel/out/save-reel.mp4

import React from 'react';
import { AbsoluteFill, Composition, Sequence, registerRoot, useCurrentFrame } from 'remotion';
import { TasteProvider } from './scenes/shared/kit/core/taste.js';
import { Letterbox } from './scenes/shared/kit/core/camera.js';
import { paleWhip } from './scenes/shared/tastes/pale-whip.js';
import { BARS, DURATION, FPS, H, W } from './scenes/lib.js';
import type { Media } from './scenes/lib.js';
import { Post } from './scenes/shots/s01.js';
import { FeedWhip } from './scenes/shots/s02.js';
import { JustLikeThat } from './scenes/shots/s03.js';
import { InYour } from './scenes/shots/s04.js';
import { Grid } from './scenes/shots/s05.js';
import { Collection } from './scenes/shots/s06.js';
import { WhatIf } from './scenes/shots/s07.js';
import { SaveReminders } from './scenes/shots/s08.js';
import { AndDone } from './scenes/shots/s09.js';
import { Gonna } from './scenes/shots/s10.js';
import { Notice } from './scenes/shots/s11.js';
import { Feed } from './scenes/shots/s12.js';
import { Photo } from './scenes/shots/s13.js';
import { Forever } from './scenes/shots/s14.js';
import { EndCard } from './scenes/shots/s15.js';
import './scenes/sound.js';

// [component, first frame, last frame (exclusive)]; neighbours overlap where the reference cross-blurs
export const SHOTS: [React.FC<{ media: Media }>, number, number][] = [
  [Post, 0, 62],
  [FeedWhip, 54, 82],
  [JustLikeThat, 80, 135],
  [InYour, 134, 153],
  [Grid, 150, 181],
  [Collection, 176, 198],
  [WhatIf, 197, 241],
  [SaveReminders, 240, 343],
  [AndDone, 342, 373],
  [Gonna, 372, 413],
  [Notice, 412, 453],
  [Feed, 447, 561],
  [Photo, 560, 761],
  [Forever, 740, 946],
  [EndCard, 939, DURATION],
];

export interface SaveReelProps {
  media: Media;
}

export const SaveReel: React.FC<SaveReelProps> = ({ media }) => {
  const frame = useCurrentFrame();
  return (
    <TasteProvider taste={paleWhip}>
      <AbsoluteFill style={{ backgroundColor: '#000' }}>
        {SHOTS.map(([Shot, from, to], i) => (
          <Sequence key={i} from={from} durationInFrames={to - from}>
            <Shot media={media} />
          </Sequence>
        ))}
        <Letterbox frame={frame} bars={BARS} />
      </AbsoluteFill>
    </TasteProvider>
  );
};

registerRoot(() => (
  <Composition
    id="SaveReel"
    component={SaveReel}
    durationInFrames={DURATION}
    fps={FPS}
    width={W}
    height={H}
    defaultProps={{ media: {} }}
  />
));

// Shared pieces of the save reel. The reusable blocks (camera, ink, icons, pointers, timing) are in the kit
// (../../kit), cut in the Pale Whip taste; this re-exports them under the names the shots use and keeps what is the
// reel's own: its constants, its pictures and the save-reminder button.

import React from 'react';
import { staticFile } from 'remotion';
import { Layer, Path, Rect, linearGradient } from '@kinetographdev/core';
import { paleWhip } from './shared/tastes/pale-whip.js';
import { line } from './shared/kit/core/draw.js';

export { line, rrect, polyD } from './shared/kit/core/draw.js';
export type { Line } from './shared/kit/core/draw.js';
export { clamp, ease, easeIn, easeOut, glide, keys, ramp, spline } from './shared/kit/core/timing.js';
export { Cam } from './shared/kit/core/camera.js';
export { InkLines, Ink, handLine, curve } from './shared/kit/core/ink.js';
export type { InkStroke } from './shared/kit/core/ink.js';
export { ICON, Icon } from './shared/kit/core/icons.js';
export { Arrow, BigArrow, FlatArrow, Hand } from './shared/kit/core/pointers.js';

export const W = 1080;
export const H = 810;
export const FPS = 30;
export const DURATION = 1166;

export const UI = paleWhip.fonts.ui;
export const WIDE = paleWhip.fonts.display;
export const MARKER = paleWhip.fonts.marker;
export const PEN = paleWhip.fonts.pen;

export const PAPER = paleWhip.canvas;
export const TEXT = paleWhip.ink;
export const GREY = paleWhip.muted;
export const RED_INK = paleWhip.notes.red;
export const YELLOW_INK = paleWhip.notes.yellow;
export const BLUE = paleWhip.accent;

// Bar height (px of 810) measured frame by frame on the reference: it opens and closes with the shots.
export const BARS: [number, number][] = [
  [0, 0], [12, 0], [18, 13], [24, 23], [27, 28], [33, 28], [39, 47], [45, 47], [48, 42], [51, 24], [54, 0],
  [135, 0], [150, 58], [174, 72], [228, 70], [240, 40], [252, 0], [266, 0], [276, 58], [290, 66],
  [300, 60], [310, 20], [338, 20], [348, 58], [400, 60], [414, 91], [444, 88], [450, 46], [456, 0], [750, 0], [810, 76],
];

// The posts' pictures are public-domain photos from the Internet Archive, in public/photos/ (sources and why each is
// public domain in public/photos/CREDITS.md; re-download with tools/fetch-photos.sh). The editor screenshot is drawn.
export const photoSrc = (file: string) => staticFile(`images/save-reel/photos/${file}`);
/** Video thumbnail n of the collection grid (any integer; there are ten photos, so they repeat). */
export const thumbSrc = (n: number) => photoSrc(`thumb-${String((((n % 10) + 10) % 10) + 1).padStart(2, '0')}.jpg`);

// To use your own pictures in the feed, put them in public/media/ and pass their names as the composition's `media`
// prop; `editor` replaces the drawn editor screenshot.
export interface Media {
  hills?: string;
  editor?: string;
  photo?: string;
}
export const mediaSrc = (file: string | undefined) => (file ? staticFile(`media/${file}`) : undefined);

/** The save-reminder bookmark: a tall bookmark with round corners and a deep notch (to 63% of its height), and a
 *  stopwatch badge over its top right corner: a thick ring with one slanted hand, cut out of the bookmark by a thin
 *  gap of the background colour (`gap`). Measured on the reference. */
export const ReminderMark: React.FC<{ size: number; filled?: boolean; color?: string; badgeBg?: string; gap?: string }> = ({
  size,
  filled = false,
  color = TEXT,
  badgeBg = '#fff',
  gap = PAPER,
}) => {
  const k = size / 24;
  const circle = (r: number) => `M18.2 ${4.2 - r}A${r} ${r} 0 1 1 18.19 ${4.2 - r}Z`;
  return (
    <Layer scale={k}>
      <Path
        d="M3.8 3H17.8V21.4L10.8 14.6 3.8 21.4Z"
        fill={filled ? color : undefined}
        stroke={line({ color, width: 2.1, join: 'round', cap: 'round' })}
      />
      <Path d={circle(5.3)} fill={gap} />
      <Path d={circle(3.9)} fill={filled ? badgeBg : gap} stroke={line({ color, width: 1.9 })} />
      <Path d="M17.6 5.5L19.1 2.9" stroke={line({ color, width: 1.8, cap: 'round' })} />
    </Layer>
  );
};

// the app's glyph: a rounded square in the warm-to-violet gradient with a camera drawn in white
export const APP_GRADIENT = linearGradient(['#fdc468', '#fa7e1e', '#e3255f', '#c13584', '#7a3fe0'], { angle: 35 });

export const AppGlyph: React.FC<{ size: number }> = ({ size }) => {
  const k = size / 100;
  return (
    <Layer scale={k}>
      <Rect width={100} height={100} radius={26} fill={APP_GRADIENT} />
      <Rect x={20} y={20} width={60} height={60} radius={18} stroke={{ color: '#fff', width: 7.5 }} />
      <Path d="M50 35A15 15 0 1 1 49.99 35Z" stroke={{ color: '#fff', width: 7.5 }} />
      <Path d="M68.5 27.5A4.5 4.5 0 1 1 68.49 27.5Z" fill="#fff" />
    </Layer>
  );
};

// The feed post the reel keeps coming back to: the kit's SocialCard with the reel's save-reminder button in its save
// slot. Laid out from (0, 0) in world pixels; every part's position is in POST so a shot can aim the camera at it.

import React from 'react';
import { SOCIAL_CARD, SocialCard } from './shared/kit/core/ui/social-card.js';
import type { SocialCardProps } from './shared/kit/core/ui/social-card.js';
import { ReminderMark } from './lib.js';

export { Avatar, Tag } from './shared/kit/core/ui/social-card.js';

export const POST = SOCIAL_CARD;

export type SaveState = 'outline' | 'filled' | 'reminder' | 'reminderFilled' | 'none';

export type PostProps = Omit<SocialCardProps, 'save'> & { save?: SaveState };

export const PostCard: React.FC<PostProps> = ({ save = 'outline', ...props }) => (
  <SocialCard
    {...props}
    save={save === 'reminder' ? <ReminderMark size={26} /> : save === 'reminderFilled' ? <ReminderMark size={26} filled /> : save}
  />
);

// Full-frame looks: the warm dark interlude gradient, and a spotlight that takes everything outside an oval to black.

import React from 'react';
import { useVideoConfig } from 'remotion';
import { Ellipse, Layer, Rect, blur, linearGradient, radialGradient } from '@kinetographdev/core';
import { line } from './draw.js';
import { useTaste } from './taste.js';

/** The taste's interlude: its warm colours along the bottom under a dark shade from the top. warmth 0..1 lets more
 *  of the colour through. */
export const WarmGradient: React.FC<{ warmth?: number }> = ({ warmth = 1 }) => {
  const { width, height } = useVideoConfig();
  const { interlude } = useTaste();
  return (
    <Layer>
      <Rect width={width} height={height} fill={linearGradient(interlude.colors, { angle: 90 })} />
      <Rect
        width={width}
        height={height}
        opacity={Math.min(1, 1.15 - warmth * 0.15)}
        fill={linearGradient([interlude.shade, interlude.shade, `${interlude.shade}c8`, `${interlude.shade}00`], { angle: 180 })}
      />
    </Layer>
  );
};

export interface Oval {
  x: number;
  y: number;
  rx: number;
  ry: number;
}

/** A spotlight in screen pixels: a soft white bloom and falloff round `light`, and everything outside `edge`
 *  (blurred by `soft`) taken to black. `edge` is usually narrower than the falloff so the frame's sides go fully
 *  dark. */
export const Spotlight: React.FC<{ light: Oval; edge: Oval; soft?: number; opacity?: number }> = ({
  light,
  edge,
  soft = 60,
  opacity = 1,
}) => {
  if (opacity <= 0) return null;
  // the gradient's box is 1.6 times the oval each way so it covers the whole canvas
  const bw = light.rx * 3.2;
  const bh = light.ry * 3.2;
  // a black ring: a stroke 1400 wide whose inner edge is the edge oval
  const t = 1400;
  return (
    <Layer opacity={opacity}>
      <Rect
        x={light.x - bw / 2}
        y={light.y - bh / 2}
        width={bw}
        height={bh}
        fill={radialGradient([
          [0, 'rgba(255,255,255,0.25)'],
          [0.19, 'rgba(255,255,255,0)'],
          [0.39, 'rgba(0,0,0,0)'],
          [0.53, 'rgba(0,0,0,0.85)'],
          [0.625, 'rgba(0,0,0,0.97)'],
          [1, 'rgba(0,0,0,0.98)'],
        ])}
      />
      <Ellipse
        x={edge.x - edge.rx - t / 2}
        y={edge.y - edge.ry - t / 2}
        width={2 * edge.rx + t}
        height={2 * edge.ry + t}
        stroke={line({ color: '#000', width: t })}
        effects={[blur(soft)]}
      />
    </Layer>
  );
};

// A 2D camera with motion blur, and the letterbox bars that open and close with the shots.

import React from 'react';
import { useVideoConfig } from 'remotion';
import { Layer, Rect } from '@kinetographdev/core';
import { useTaste } from './taste.js';
import { keys } from './timing.js';

/** Children are in world pixels; the point (x, y) lands in the middle of the canvas, magnified zoom times. Moving
 *  it fast is a whip: the motion blur (shutter in frames, the taste's by default) smears it.
 *
 *  Two things keep the blur whole across cuts. Give every Cam an `id`, unique among the shots on screen at once: a
 *  blurred layer's sub-frames are matched by id, and automatic ids shift when a neighbouring Sequence mounts or
 *  unmounts, which drops samples (the layer fades). And sub-frames before a Sequence's first frame draw nothing, so
 *  start a whipping shot's Sequence a few frames early, hide it with `opacity` until `start - 0.5`, and give its
 *  camera a key there so it is already moving. */
export const Cam: React.FC<{
  id?: string;
  x: number;
  y: number;
  zoom?: number;
  rotation?: number;
  /** shutter, frames; 0 turns the blur off */
  blur?: number;
  children: React.ReactNode;
}> = ({ id, x, y, zoom = 1, rotation = 0, blur, children }) => {
  const { width, height } = useVideoConfig();
  const { camera } = useTaste();
  const shutter = blur ?? camera.shutter;
  return (
    <Layer id={id} motionBlur={shutter > 0 ? { samples: camera.samples, shutter } : undefined}>
      <Layer x={width / 2} y={height / 2} scale={zoom} rotation={rotation}>
        <Layer x={-x} y={-y}>{children}</Layer>
      </Layer>
    </Layer>
  );
};

/** Bars top and bottom, `bars` keyframes of their height ([[frame, px], ...], eased between). */
export const Letterbox: React.FC<{ frame: number; bars: [number, number][] }> = ({ frame, bars }) => {
  const { width, height } = useVideoConfig();
  const taste = useTaste();
  const h = keys(frame, bars);
  if (h < 0.5) return null;
  return (
    <Layer>
      <Rect width={width} height={h} fill={taste.bars} />
      <Rect y={height - h} width={width} height={h} fill={taste.bars} />
    </Layer>
  );
};

// Small drawing helpers: a fully typed stroke and rounded-rectangle path data.

import type { Stroke } from '@kinetographdev/scene';

// SCENE.md's stroke takes cap, join and dashes; the TS type only names colour and width.
export interface Line {
  color: string;
  width: number;
  cap?: 'butt' | 'round' | 'square';
  join?: 'miter' | 'round' | 'bevel';
  dashArray?: number[];
  dashOffset?: number;
}
export const line = (l: Line) => l as Stroke;

/** A rounded rectangle as path data, for clips (a group's clip takes a path, not a box). */
export const rrect = (w: number, h: number, r: number, x = 0, y = 0) =>
  `M${x + r} ${y}H${x + w - r}A${r} ${r} 0 0 1 ${x + w} ${y + r}V${y + h - r}A${r} ${r} 0 0 1 ${x + w - r} ${y + h}` +
  `H${x + r}A${r} ${r} 0 0 1 ${x} ${y + h - r}V${y + r}A${r} ${r} 0 0 1 ${x + r} ${y}Z`;

/** Points as a polyline's path data. */
export const polyD = (pts: number[][]) => pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(2)} ${p[1].toFixed(2)}`).join(' ');

// Line icons in 24-unit boxes, drawn at size / 24 in the taste's ink.

import React from 'react';
import { Layer, Path } from '@kinetographdev/core';
import { line } from './draw.js';
import { useTaste } from './taste.js';

export const ICON = {
  heart:
    'M12 20.6C12 20.6 3 15.2 3 9.1 3 6.3 5.1 4.2 7.7 4.2 9.5 4.2 11.1 5.2 12 6.7 12.9 5.2 14.5 4.2 16.3 4.2 18.9 4.2 21 6.3 21 9.1 21 15.2 12 20.6 12 20.6Z',
  comment: 'M20.4 16.6A9 9 0 1 0 16.6 20.4L21.5 21.5Z',
  repost: 'M4.5 12.5V9.5A3 3 0 0 1 7.5 6.5H18.5M15.5 3.5L18.5 6.5 15.5 9.5M19.5 11.5V14.5A3 3 0 0 1 16.5 17.5H5.5M8.5 20.5L5.5 17.5 8.5 14.5',
  send: 'M21.5 3L3 9.4 10.3 12.6 13.6 21Z M10.3 12.6L21.5 3',
  bookmark: 'M18.5 21L12 15.3 5.5 21V3.5H18.5Z',
  dots: 'M5 12h.01M12 12h.01M19 12h.01',
  calendar: 'M4 6.5A1.5 1.5 0 0 1 5.5 5H18.5A1.5 1.5 0 0 1 20 6.5V19A1.5 1.5 0 0 1 18.5 20.5H5.5A1.5 1.5 0 0 1 4 19Z M4 10H20 M8.5 3V7 M15.5 3V7',
  clock: 'M12 3A9 9 0 1 1 11.99 3Z M12 7.5V12L15 13.5',
  chevron: 'M7 10L12 15 17 10',
};

export const Icon: React.FC<{
  d: string;
  size: number;
  color?: string;
  fill?: string;
  stroke?: number;
  x?: number;
  y?: number;
  scale?: number;
  opacity?: number;
}> = ({ d, size, color, fill, stroke = 2.3, x = 0, y = 0, scale = 1, opacity = 1 }) => {
  const taste = useTaste();
  return (
    <Layer x={x} y={y} scale={(size / 24) * scale} opacity={opacity}>
      <Path
        d={d}
        fill={fill}
        stroke={stroke > 0 ? line({ color: color ?? taste.ink, width: stroke, cap: 'round', join: 'round' }) : undefined}
      />
    </Layer>
  );
};

// Hand-written notes: words written on in a handwriting font, and freehand lines (underlines, arrows, scribbles)
// drawn on along their length.

import React from 'react';
import { random } from 'remotion';
import { measureText } from '@remotion/layout-utils';
import { Layer, Path, Text } from '@kinetographdev/core';
import { line, polyD } from './draw.js';
import { useTaste } from './taste.js';
import { ramp } from './timing.js';

export interface InkStroke {
  pts: number[][];
  len: number;
}

/** Strokes drawn on in order, by length: progress 0 is nothing, 1 the whole of them. */
export const InkLines: React.FC<{
  strokes: InkStroke[];
  progress: number;
  color: string;
  width: number;
  effects?: unknown[];
}> = ({ strokes, progress, color, width, effects }) => {
  const total = strokes.reduce((a, b) => a + b.len, 0);
  let left = Math.max(0, Math.min(1, progress)) * total;
  return (
    <Layer effects={effects as never}>
      {strokes.map((st, i) => {
        const show = Math.min(st.len, left);
        left -= st.len;
        if (show <= 0.01) return null;
        return (
          <Path
            key={i}
            d={polyD(st.pts)}
            stroke={line({ color, width, cap: 'round', join: 'round', dashArray: [show, st.len + 1000] })}
          />
        );
      })}
    </Layer>
  );
};

/** A handwritten word at (x, y) (its baseline), written on left to right between frames start and end: the word
 *  in the taste's marker or pen font, uncovered by a slanted edge that runs along it as a pen would. */
export const Ink: React.FC<{
  text: string;
  frame: number;
  start: number;
  end: number;
  x: number;
  y: number;
  size: number;
  color: string;
  hand?: 'marker' | 'pen';
  rotation?: number;
  effects?: unknown[];
}> = ({ text, frame, start, end, x, y, size, color, hand = 'marker', rotation = 0, effects }) => {
  const { fonts } = useTaste();
  const font = hand === 'marker' ? fonts.marker : fonts.pen;
  const weight = 400;
  const w = measureText({ text, fontFamily: font, fontSize: size, fontWeight: String(weight) }).width;
  const p = ramp(frame, start, end, 0, 1, (t) => t);
  if (p <= 0) return null;
  // the text box's top sits about 0.8 of the size above the baseline in handwriting fonts
  const top = -size * 0.8;
  const edge = -size * 0.1 + p * (w + size * 0.3);
  const lean = size * 0.25;
  return (
    <Layer x={x} y={y} rotation={rotation}>
      <Layer
        effects={effects as never}
        clip={{
          kind: 'polygon',
          points: [
            [-size, top - size],
            [edge + lean, top - size],
            [edge - lean, size * 0.6],
            [-size, size * 0.6],
          ],
        }}
      >
        <Text font={font} weight={weight} size={size} color={color} x={0} y={top}>
          {text}
        </Text>
      </Layer>
    </Layer>
  );
};

/** A freehand line through points (an arrow's shaft, an underline), with a little seeded wobble. */
export function handLine(points: number[][], seed: string, wobble = 1.5): InkStroke {
  const pts: number[][] = [];
  for (let i = 0; i < points.length - 1; i++) {
    const [ax, ay] = points[i];
    const [bx, by] = points[i + 1];
    const n = Math.max(2, Math.ceil(Math.hypot(bx - ax, by - ay) / 6));
    for (let k = i ? 1 : 0; k <= n; k++) {
      const t = k / n;
      pts.push([ax + (bx - ax) * t + (random(`${seed}-${i}-${k}-x`) - 0.5) * wobble, ay + (by - ay) * t + (random(`${seed}-${i}-${k}-y`) - 0.5) * wobble]);
    }
  }
  // smooth once so the wobble reads as a hand, not noise
  const sm = pts.map((p, i) => (i === 0 || i === pts.length - 1 ? p : [(pts[i - 1][0] + 2 * p[0] + pts[i + 1][0]) / 4, (pts[i - 1][1] + 2 * p[1] + pts[i + 1][1]) / 4]));
  let len = 0;
  for (let i = 1; i < sm.length; i++) len += Math.hypot(sm[i][0] - sm[i - 1][0], sm[i][1] - sm[i - 1][1]);
  return { pts: sm, len };
}

/** Points along a quadratic curve from a to b bending through c. */
export function curve(a: number[], c: number[], b: number[], n = 16): number[][] {
  return Array.from({ length: n + 1 }, (_, i) => {
    const t = i / n;
    const u = 1 - t;
    return [u * u * a[0] + 2 * u * t * c[0] + t * t * b[0], u * u * a[1] + 2 * u * t * c[1] + t * t * b[1]];
  });
}

// Pointers: the screen cursor, a tapping hand, a fat flat block arrow, and the same arrow extruded in 3D.

import React from 'react';
import { Layer, Path, blur, dropShadow } from '@kinetographdev/core';
import { line } from './draw.js';

/** A chunky screen cursor, tip at (0, 0). */
export const Arrow: React.FC<{ size?: number; color?: string; outline?: string }> = ({ size = 28, color = '#fff', outline = '#111' }) => (
  <Layer scale={size / 24} effects={[dropShadow({ y: 1, blur: 1.5, color: '#00000055' })]}>
    <Path
      d="M2.6 2.2L2.6 19 6.9 15.3 9.8 21.6 12.9 20.3 10.1 14.2 16.2 14.2Z"
      fill={color}
      stroke={line({ color: outline, width: 1.6, join: 'round' })}
    />
  </Layer>
);

/** A pointing hand; pressed 0..1 shrinks it a little, as a tap. */
export const Hand: React.FC<{ size?: number; pressed?: number }> = ({ size = 34, pressed = 0 }) => (
  <Layer scale={(size / 24) * (1 - pressed * 0.08)}>
    <Path
      d="M8.6 12.8V4.4A1.6 1.6 0 0 1 11.8 4.4V10.6 9.4A1.6 1.6 0 0 1 15 9.4V11 10.3A1.6 1.6 0 0 1 18.2 10.3V11.8 11.6A1.5 1.5 0 0 1 21.2 11.6V16.4C21.2 20 18.8 22.6 15.4 22.6H13.2C11.2 22.6 9.9 21.8 8.7 20.3L4.6 15.2A1.6 1.6 0 0 1 6.9 12.9Z"
      fill="#fff"
      stroke={line({ color: '#111', width: 1.3, join: 'round' })}
    />
  </Layer>
);

// the block arrow both pointers share: tip at (0, 0) pointing right, tail at x = -100 (units)
const BLOCK: [number, number][] = [
  [0, 0], [-44, -30], [-44, -13], [-90, -11], [-97, -8], [-100, 0], [-97, 8], [-90, 11], [-44, 13], [-44, 30],
];
const poly = (pts: [number, number][]) => pts.map(([x, y], i) => `${i ? 'L' : 'M'}${x.toFixed(2)} ${y.toFixed(2)}`).join(' ') + 'Z';

/** A fat white block arrow with soft round edges and no outline, tip at (0, 0) pointing right. */
export const FlatArrow: React.FC<{ size: number }> = ({ size }) => (
  <Layer scale={size / 100} effects={[dropShadow({ y: 2, blur: 3, color: '#00000040' })]}>
    <Path d={poly(BLOCK)} fill="#fbfbfb" stroke={line({ color: '#fbfbfb', width: 9, join: 'round' })} effects={[blur(1.2)]} />
  </Layer>
);

/** The block arrow extruded, seen in perspective (yawed and tilted towards the viewer), tip at (0, 0) pointing
 *  right. It spins about its long axis: spin 0 (or 180) shows the white face, 90 the dark edge. */
export const BigArrow: React.FC<{ size: number; spin?: number; yaw?: number; tilt?: number }> = ({
  size,
  spin = 0,
  yaw = -24,
  tilt = 26,
}) => {
  const k = size / 100;
  const depth = 16;
  const focal = 340;
  const ra = (spin * Math.PI) / 180;
  const rb = (yaw * Math.PI) / 180;
  const rc = (tilt * Math.PI) / 180;
  // rotate about the long (x) axis by spin, then the fixed tilt (about x) and yaw (about y), then project
  const project = ([x, y]: [number, number], z: number): [number, number, number] => {
    let y1 = y * Math.cos(ra) - z * Math.sin(ra);
    let z1 = y * Math.sin(ra) + z * Math.cos(ra);
    const y2 = y1 * Math.cos(rc) - z1 * Math.sin(rc);
    const z2 = y1 * Math.sin(rc) + z1 * Math.cos(rc);
    y1 = y2;
    z1 = z2;
    const x3 = x * Math.cos(rb) + z1 * Math.sin(rb);
    const z3 = -x * Math.sin(rb) + z1 * Math.cos(rb);
    const sc = focal / (focal - z3);
    return [x3 * sc, y1 * sc, z3];
  };
  const front = BLOCK.map((p) => project(p, depth / 2));
  const back = BLOCK.map((p) => project(p, -depth / 2));
  const xy = (pts: [number, number, number][]) => pts.map(([x, y]) => [x, y] as [number, number]);
  // which face looks at us: the front's normal (0, 0, 1) after the turns
  const nz = Math.cos(ra) * Math.cos(rc) * Math.cos(rb) - Math.sin(ra) * Math.sin(rc) * Math.cos(rb);
  const [near, far] = nz >= 0 ? [front, back] : [back, front];
  const faceTone = nz >= 0 ? '#ffffff' : '#ececf0';
  const sides = BLOCK.map((_, i) => {
    const j = (i + 1) % BLOCK.length;
    const quad = [front[i], front[j], back[j], back[i]];
    return { quad, z: quad.reduce((a, q) => a + q[2], 0) / 4 };
  }).sort((a, b) => a.z - b.z);
  return (
    <Layer scale={k}>
      <Layer x={10} y={18} opacity={0.32}>
        <Path d={poly(xy(near))} fill="#000" effects={[blur(7)]} />
      </Layer>
      <Path d={poly(xy(far))} fill="#36363a" stroke={line({ color: '#36363a', width: 2, join: 'round' })} />
      {sides.map((sd, i) => (
        <Path key={i} d={poly(xy(sd.quad))} fill="#3c3c41" stroke={line({ color: '#3c3c41', width: 1.6, join: 'round' })} />
      ))}
      <Path
        d={poly(xy(near))}
        fill={faceTone}
        stroke={line({ color: '#26262a', width: 3.4, join: 'round' })}
        opacity={Math.min(1, Math.abs(nz) * 5)}
      />
    </Layer>
  );
};

// Synthesised sound effects for the reels, written with onFrame from @kinetographdev/audio: whooshes for camera
// whips, clicks for taps, pops for things that appear, a thud, pen scratch, page flicks, and plain tones for beds and
// chimes.
// Everything runs through one bus with a limiter and a soft clip. Noise comes from `random(seed)`, never the clock,
// so a render is repeatable.
//
//   onFrame(whipFrame - 4, (ctx, t) => whoosh(ctx, t));
//   onFrame(tapFrame, (ctx, t) => click(ctx, t));
//
// These are placeholders with good timing: swap in recorded sounds at the same frames when you have them.

import { random } from 'remotion';
import type { OnFrameCallback } from '@kinetographdev/audio';

export type Ctx = Parameters<OnFrameCallback>[0];

const outs = new WeakMap<Ctx, { bus: GainNode; noise: AudioBuffer }>();
function out(ctx: Ctx) {
  let o = outs.get(ctx);
  if (!o) {
    const noise = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
    const d = noise.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = random(`noise-${i}`) * 2 - 1;
    // a hard compressor, then the make-up gain, then a soft clip so no transient goes past full scale
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -18;
    limiter.knee.value = 0;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.001;
    limiter.release.value = 0.2;
    const makeup = ctx.createGain();
    makeup.gain.value = 0.7;
    const clip = ctx.createWaveShaper();
    const curve = new Float32Array(1025);
    for (let i = 0; i < curve.length; i++) curve[i] = Math.tanh(((i / 1024) * 2 - 1) * 1.2) / Math.tanh(1.2) * 0.85;
    clip.curve = curve;
    const bus = ctx.createGain();
    bus.gain.value = 2;
    bus.connect(limiter).connect(makeup).connect(clip).connect(ctx.destination);
    o = { bus, noise };
    outs.set(ctx, o);
  }
  return o;
}

function noiseSrc(ctx: Ctx, t: number, len: number) {
  const src = ctx.createBufferSource();
  src.buffer = out(ctx).noise;
  src.loop = true;
  src.start(t, random(`off-${t}`) * 0.9);
  src.stop(t + len + 0.02);
  return src;
}

/** Filtered noise swelling and sweeping up then down: a camera whip. */
export function whoosh(ctx: Ctx, t: number, len = 0.35, level = 0.35, from = 400, peak = 3200) {
  const bp = ctx.createBiquadFilter();
  bp.type = 'bandpass';
  bp.Q.value = 0.9;
  bp.frequency.setValueAtTime(from, t);
  bp.frequency.exponentialRampToValueAtTime(peak, t + len * 0.55);
  bp.frequency.exponentialRampToValueAtTime(from, t + len);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(level, t + len * 0.55);
  g.gain.exponentialRampToValueAtTime(0.0001, t + len);
  noiseSrc(ctx, t, len).connect(bp).connect(g).connect(out(ctx).bus);
}

/** A short tick: UI taps and toggles. */
export function click(ctx: Ctx, t: number, freq = 2400, level = 0.25) {
  const o = ctx.createOscillator();
  o.type = 'triangle';
  o.frequency.setValueAtTime(freq, t);
  o.frequency.exponentialRampToValueAtTime(freq * 0.5, t + 0.03);
  const g = ctx.createGain();
  g.gain.setValueAtTime(level, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + 0.04);
  o.connect(g).connect(out(ctx).bus);
  o.start(t);
  o.stop(t + 0.05);
}

/** A rounded pop for things that appear (the sheet, the notification). */
export function pop(ctx: Ctx, t: number, freq = 520, level = 0.3) {
  const o = ctx.createOscillator();
  o.type = 'sine';
  o.frequency.setValueAtTime(freq * 0.6, t);
  o.frequency.exponentialRampToValueAtTime(freq * 1.6, t + 0.06);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(level, t + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0001, t + 0.12);
  o.connect(g).connect(out(ctx).bus);
  o.start(t);
  o.stop(t + 0.14);
}

export function thud(ctx: Ctx, t: number, level = 0.6) {
  const o = ctx.createOscillator();
  o.frequency.setValueAtTime(140, t);
  o.frequency.exponentialRampToValueAtTime(45, t + 0.18);
  const g = ctx.createGain();
  g.gain.setValueAtTime(level, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + 0.25);
  o.connect(g).connect(out(ctx).bus);
  o.start(t);
  o.stop(t + 0.27);
}

/** A page flicked over: a short burst of bright noise with a papery band, `key` varying each one. */
export function flick(ctx: Ctx, t: number, key: string, level = 0.18) {
  const hp = ctx.createBiquadFilter();
  hp.type = 'highpass';
  hp.frequency.value = 1800;
  const bp = ctx.createBiquadFilter();
  bp.type = 'peaking';
  bp.frequency.value = 3000 + random(`${key}-f`) * 3000;
  bp.gain.value = 8;
  const g = ctx.createGain();
  const len = 0.05 + random(`${key}-l`) * 0.04;
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(level * (0.7 + random(`${key}-g`) * 0.3), t + 0.004);
  g.gain.exponentialRampToValueAtTime(0.001, t + len);
  noiseSrc(ctx, t, len).connect(hp).connect(bp).connect(g).connect(out(ctx).bus);
}

/** Pen on paper: band-passed noise in short strokes. */
export function scratch(ctx: Ctx, t: number, len: number, key: string, level = 0.12) {
  const bp = ctx.createBiquadFilter();
  bp.type = 'bandpass';
  bp.Q.value = 2;
  const g = ctx.createGain();
  g.gain.setValueAtTime(0, t);
  for (let s = 0, i = 0; s < len; i++) {
    const step = 0.05 + random(`${key}-s${i}`) * 0.08;
    g.gain.setValueAtTime(0, t + s);
    g.gain.linearRampToValueAtTime(level * (0.5 + random(`${key}-g${i}`) * 0.5), t + s + step * 0.4);
    g.gain.linearRampToValueAtTime(0, t + s + step);
    bp.frequency.setValueAtTime(2500 + random(`${key}-f${i}`) * 3500, t + s);
    s += step;
  }
  noiseSrc(ctx, t, len).connect(bp).connect(g).connect(out(ctx).bus);
}

export function tone(ctx: Ctx, t: number, len: number, freq: number, level: number, type: OscillatorType, attack: number, release: number) {
  const o = ctx.createOscillator();
  o.type = type;
  o.frequency.value = freq;
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.value = 1800;
  const g = ctx.createGain();
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(level, t + attack);
  g.gain.setValueAtTime(level, t + Math.max(attack, len - release));
  g.gain.linearRampToValueAtTime(0, t + len);
  o.connect(lp).connect(g).connect(out(ctx).bus);
  o.start(t);
  o.stop(t + len + 0.01);
}

export const hz = (midi: number) => 440 * 2 ** ((midi - 69) / 12);

// A taste: the style a component is cut in (palette, fonts, camera blur, easing, bars), as one value. Kit components
// read it from context, so a component wraps its root in <TasteProvider taste={...}> and the same blocks restyle
// when the taste changes. Tastes live in kit/tastes/.

import React, { createContext, useContext } from 'react';
import { paleWhip } from '../../tastes/pale-whip.js';

export type Rgb = [number, number, number];

export interface Taste {
  name: string;
  /** the page the UI sits on */
  canvas: string;
  /** body text and icon strokes */
  ink: string;
  /** secondary text */
  muted: string;
  /** buttons, links, the selected state */
  accent: string;
  /** a toggle's track, off and on (rgb, so it can be blended) */
  toggle: { off: Rgb; on: Rgb };
  /** the ring round an avatar */
  avatarRing: string[];
  fonts: {
    /** interface type */
    ui: string;
    /** big display words */
    display: string;
    /** the felt-tip notes */
    marker: string;
    /** the thin pen notes */
    pen: string;
  };
  /** colours of the hand-written notes */
  notes: { red: string; yellow: string };
  /** the dark interludes between UI shots: a warm gradient along the bottom under a dark shade from the top */
  interlude: { colors: string[]; shade: string };
  camera: {
    /** motion-blur samples per frame */
    samples: number;
    /** default shutter, in frames (0 to 2); whips read best at 1.4 to 1.6 */
    shutter: number;
  };
  /** letterbox bar colour */
  bars: string;
}

const TasteContext = createContext<Taste>(paleWhip);

export const TasteProvider: React.FC<{ taste: Taste; children: React.ReactNode }> = ({ taste, children }) => (
  <TasteContext.Provider value={taste}>{children}</TasteContext.Provider>
);

/** The taste in effect (Pale Whip outside a provider). */
export const useTaste = () => useContext(TasteContext);

// Frame-based timing: eases, keyframes, ramps, and two smooth curves for camera paths measured key by key.

import { Easing, interpolate } from 'remotion';

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
export const ease = Easing.bezier(0.45, 0, 0.15, 1);
export const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
export const easeIn = Easing.bezier(0.7, 0, 0.84, 0);

/** interpolate over keyframes [[frame, value], ...] with one easing for every segment */
export function keys(f: number, k: [number, number][], easing: (t: number) => number = ease): number {
  if (f <= k[0][0]) return k[0][1];
  for (let i = 1; i < k.length; i++) {
    if (f <= k[i][0]) {
      const [a, va] = k[i - 1];
      const [b, vb] = k[i];
      return va + (vb - va) * easing((f - a) / (b - a));
    }
  }
  return k[k.length - 1][1];
}

/** from at frame a to to at frame b, held outside */
export const ramp = (f: number, a: number, b: number, from: number, to: number, easing = ease) =>
  interpolate(f, [a, b], [from, to], { ...clamp, easing });

/** A smooth curve through [frame, value] keys (cubic Hermite, finite-difference slopes, flat at the ends and where
 *  the direction turns), so a camera measured key by key moves without stopping at every key. */
export function spline(f: number, k: [number, number][]): number {
  if (f <= k[0][0]) return k[0][1];
  const n = k.length - 1;
  if (f >= k[n][0]) return k[n][1];
  const slope = (i: number) => {
    if (i === 0 || i === n) return 0;
    const a = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const b = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return a * b <= 0 ? 0 : (k[i + 1][1] - k[i - 1][1]) / (k[i + 1][0] - k[i - 1][0]);
  };
  let i = 0;
  while (f > k[i + 1][0]) i++;
  const [t0, v0] = k[i];
  const [t1, v1] = k[i + 1];
  const h = t1 - t0;
  const t = (f - t0) / h;
  const t2 = t * t;
  const t3 = t2 * t;
  return (2 * t3 - 3 * t2 + 1) * v0 + (t3 - 2 * t2 + t) * h * slope(i) + (-2 * t3 + 3 * t2) * v1 + (t3 - t2) * h * slope(i + 1);
}

/** Monotone cubic through keys [[frame, value], ...]: a camera that glides through its marks without stopping or
 *  overshooting them. */
export function glide(f: number, k: [number, number][]): number {
  const n = k.length;
  if (f <= k[0][0]) return k[0][1];
  if (f >= k[n - 1][0]) return k[n - 1][1];
  const d = k.map((_, i) => {
    if (i === 0 || i === n - 1) return 0;
    const s0 = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const s1 = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return s0 * s1 <= 0 ? 0 : (2 * s0 * s1) / (s0 + s1);
  });
  let i = 1;
  while (f > k[i][0]) i++;
  const [x0, y0] = k[i - 1];
  const [x1, y1] = k[i];
  const hh = x1 - x0;
  const t = (f - x0) / hh;
  const t2 = t * t;
  const t3 = t2 * t;
  return (
    (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * hh * d[i - 1] + (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * hh * d[i]
  );
}

// A phone notification at a big design size (NOTIFICATION, 1265 x 281): app icon, title, a body line with an
// optional trailing piece (an emoji, a badge), and "now". Bring your own app icon; no app's branding is built in.

import React from 'react';
import { measureText } from '@remotion/layout-utils';
import { Layer, Rect, Text, dropShadow } from '@kinetographdev/core';
import { useTaste } from '../taste.js';

export const NOTIFICATION = { width: 1265, height: 281, radius: 40 };

export const NotificationCard: React.FC<{
  /** the app icon, drawn in a 189 px box */
  icon: React.ReactNode;
  title: string;
  body: string;
  /** drawn just after the body's last letter, with its top at the body's top */
  trailing?: React.ReactNode;
  /** 0..1: a card behind another greys its words, not its icon */
  dim?: number;
  /** 0..1: a pink wash, for a card still landing */
  tint?: number;
  now?: boolean;
}> = ({ icon, title, body, trailing, dim = 0, tint = 0, now = true }) => {
  const taste = useTaste();
  const UI = taste.fonts.ui;
  const { width: w, height: h, radius } = NOTIFICATION;
  const bodyEnd = 254 + measureText({ text: body, fontFamily: UI, fontSize: 46, fontWeight: '500' }).width;
  return (
    <Layer>
      <Rect width={w} height={h} radius={radius} fill="#fff" effects={[dropShadow({ y: 6, blur: 16, color: '#00000016' })]} />
      <Layer x={35} y={46}>
        {icon}
      </Layer>
      <Layer opacity={1 - dim}>
        <Text font={UI} weight={700} size={60} color={taste.ink} x={254} y={58}>
          {title}
        </Text>
        <Text font={UI} weight={500} size={46} color="#2a2a2e" x={254} y={145}>
          {body}
        </Text>
        {trailing && (
          <Layer x={bodyEnd} y={136}>
            {trailing}
          </Layer>
        )}
      </Layer>
      {now && (
        <Text font={UI} weight={500} size={30} color="#a2a2a8" x={w - 100} y={32}>
          now
        </Text>
      )}
      {tint > 0 && <Rect width={w} height={h} radius={radius} fill="#f6b6c9" opacity={tint} />}
    </Layer>
  );
};

// A generic social-feed post: header (avatar, name, a grey line, Follow, more), the picture, the action row (like,
// comment, repost, send, save) and the caption, in the taste's type and colours. No app's branding: the save icon is
// a slot. Laid out from (0, 0) in world pixels; every part's position is in SOCIAL_CARD so a shot can aim the camera
// at it.

import React from 'react';
import { measureText } from '@remotion/layout-utils';
import { Ellipse, Layer, Rect, Text, linearGradient } from '@kinetographdev/core';
import { line, rrect } from '../draw.js';
import { ICON, Icon } from '../icons.js';
import { useTaste } from '../taste.js';

export const SOCIAL_CARD = {
  width: 480,
  header: 64, // header height; the picture starts here
  imageHeight: 340,
  radius: 22,
  /** y of the action row's centre, given the picture height */
  actionsY: (imageHeight: number) => 64 + imageHeight + 30,
  /** y of the caption's first line */
  captionY: (imageHeight: number) => 64 + imageHeight + 58,
};

export interface SocialCardProps {
  name?: string;
  sub?: string; // the grey line under the name
  subStrong?: string; // its bold tail
  image: React.ReactNode; // drawn into a box SOCIAL_CARD.width x imageHeight, clipped to the rounded corners
  imageHeight?: number;
  likes?: string;
  comments?: string;
  reposts?: string;
  liked?: number; // 0..1: the heart fills red
  /** the save button: a bookmark outline, filled, nothing, or your own icon (24 units, drawn at 26 px) */
  save?: 'outline' | 'filled' | 'none' | React.ReactNode;
  saveScale?: number;
  caption?: string[]; // lines; the first starts with the name in bold
  captionOpacity?: number;
  darkAvatar?: boolean; // a plain black disc instead of the blank profile picture
  tag?: string; // a dark label on the caption ("[ That reference ]")
  tagX?: number;
  headerOpacity?: number;
  follow?: boolean; // the Follow button
}

export const Avatar: React.FC<{ size: number; dark?: boolean }> = ({ size, dark = false }) => {
  const taste = useTaste();
  return dark ? (
    <Ellipse width={size} height={size} fill="#111" />
  ) : (
    <Layer>
      <Ellipse width={size} height={size} fill={linearGradient(taste.avatarRing, { angle: 45 })} />
      <Ellipse x={2.5} y={2.5} width={size - 5} height={size - 5} fill={taste.canvas} />
      <Ellipse x={5} y={5} width={size - 10} height={size - 10} fill="#d9d9de" />
      <Ellipse x={size / 2 - 5} y={size / 2 - 7} width={10} height={14} fill="#7c7c84" />
    </Layer>
  );
};

export const SocialCard: React.FC<SocialCardProps> = ({
  name = 'yourhandle',
  darkAvatar = false,
  sub,
  subStrong,
  image,
  imageHeight = SOCIAL_CARD.imageHeight,
  likes = '2.1K',
  comments = '115',
  reposts = '50',
  liked = 0,
  save = 'outline',
  saveScale = 1,
  caption = [],
  captionOpacity = 1,
  tag,
  tagX = 170,
  headerOpacity = 1,
  follow = true,
}) => {
