// Shot 07 (197-240): "But, what if [app]" on black over an LED dot matrix. "But," blurs in big, "what", "if" and
// the app glyph follow while the camera eases back; from 214 coloured light (red above, violet below left, amber
// above right) blooms through the dots, then the line whips out to the left.

import React from 'react';
import { random, useCurrentFrame } from 'remotion';
import { Canvas, Ellipse, Layer, Rect, Text, blur, radialGradient } from '@kinetographdev/core';
import { AppGlyph, H, UI, W, keys, ramp } from '../lib.js';
import { textWidth } from './b-common.js';

const FROM = 197;
const lin = (t: number) => t;

// The line's total width at scale 1 (measured on the reference at 228), its left edge and scale over time.
const LINE_W = 476;
const LEFT: [number, number][] = [
  [197, 310], [199, 390], [203, 440], [209, 436], [212, 410], [216, 340], [222, 300], [228, 284], [234, 250],
  [237, 232], [239, 130], [241, -160],
];
const SCALE: [number, number][] = [
  [197, 2.8], [199, 2.1], [203, 1.33], [209, 1.27], [212, 1.25], [216, 1.17], [222, 1.03], [228, 1], [236, 0.98],
];
const CY = 402;

// colour light that blooms through the matrix: x, y (fractions), colour, drift per frame
const LIGHTS: [number, number, string, number, number][] = [
  [0.5, 0.0, '#e01a30', 0.0025, 0.001],
  [0.35, 1.0, '#b21ce8', 0.004, -0.002],
  [0.9, 0.15, '#d88a22', -0.002, 0.002],
  [0.95, 0.95, '#c42a70', -0.003, -0.001],
  [0.02, 0.1, '#3a40ff', 0.002, 0.003],
];

const hex = (c: string) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));

/** The matrix: grey dots in lit blocks, fewer round the text, zooming out; later tinted by the lights. */
function drawDots(ctx: CanvasRenderingContext2D, g: number) {
  const pitch = keys(g, [[197, 54], [203, 46], [212, 34], [222, 27.5], [228, 26]], lin);
  const fill = keys(g, [[197, 0.3], [212, 0.5], [220, 0.65], [228, 0.85], [240, 0.95]], lin);
  const colour = ramp(g, 212, 228, 0, 1);
  const step = Math.floor(g / 3);
  const lights = LIGHTS.map(([x, y, c, dx, dy]) => ({ x: (x + dx * (g - 214)) * W, y: (y + dy * (g - 214)) * H, rgb: hex(c) }));
  const cols = Math.ceil(W / pitch / 2) + 1;
  const rows = Math.ceil(H / pitch / 2) + 1;
  const r = pitch * 0.17;
  for (let j = -rows; j <= rows; j++) {
    for (let i = -cols; i <= cols; i++) {
      const x = W / 2 + i * pitch;
      const y = H / 2 + j * pitch;
      // lit in blocks of 4 x 2 dots, re-dealt every 3 frames, then dot by dot
      const block = random(`dm-b-${Math.floor(i / 4)}-${Math.floor(j / 2)}-${step}`);
      const dot = random(`dm-d-${i}-${j}-${Math.floor(step / 2)}`);
      if (block > fill + 0.15 || dot > fill + 0.35) continue;
      // darker round the words
      const dx = (x - 540) / 520;
      const dy = (y - 400) / 170;
      const hush = Math.min(1, 0.1 + 0.9 * (dx * dx + dy * dy)) * (1 - colour * 0.3) + colour * 0.3;
      const lum = (0.22 + 0.48 * random(`dm-l-${i}-${j}-${step}`)) * hush * ramp(g, 197, 206, 0.25, 1);
      let rr = 200;
      let gg = 200;
      let bb = 200;
      let glow = 1;
      if (colour > 0) {
        // tinted only near a light; between the lights the dots go dim
        let cr = 0;
        let cg = 0;
        let cb = 0;
        let wsum = 0;
        for (const l of lights) {
          const d = Math.hypot(x - l.x, y - l.y) / 460;
          const w = Math.exp(-d * d * (l === lights[4] ? 30 : 4));
          cr += l.rgb[0] * w;
          cg += l.rgb[1] * w;
          cb += l.rgb[2] * w;
          wsum += w;
        }
        const m = Math.min(1, wsum) * colour;
        const n = Math.max(wsum, 1);
        rr = rr * (1 - m) + (cr / n) * m;
        gg = gg * (1 - m) + (cg / n) * m;
        bb = bb * (1 - m) + (cb / n) * m;
        glow = 1 - colour * 0.45 + m * 0.5;
      }
      ctx.globalAlpha = Math.min(1, lum * glow);
      ctx.fillStyle = `rgb(${rr | 0},${gg | 0},${bb | 0})`;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

export const WhatIf: React.FC = () => {
  const g = useCurrentFrame() + FROM;

  const base = 100;
  const butW = textWidth('But', UI, base, 800);
  const wBut = butW + textWidth(',', UI, base, 400);
  const wWhat = textWidth('what', UI, base, 400);
  const wSpace = textWidth(' ', UI, base, 400);
  const wIf = textWidth('if', UI, base, 400);
  const total = wBut + 4 + wWhat + wSpace + wIf + 24 + base * 1.15;
  const size = (LINE_W / total) * base;
  const k = size / base;
  const xs = [0, (wBut + 4) * k, (wBut + 4 + wWhat + wSpace) * k, (wBut + 4 + wWhat + wSpace + wIf + 24) * k];
  const glyph = size * 1.15;

  const word = (a: number, dur: number, from: number) => ({
    opacity: ramp(g, a, a + 2, 0, 1),
    effects: g < a + dur ? [blur(ramp(g, a, a + dur, from, 0))] : undefined,
  });
  const top = CY - size * 0.6;
  const colour = ramp(g, 212, 228, 0, 1);

  return (
    <Layer>
      <Rect width={W} height={H} fill="#030303" />
      {colour > 0 && (
        <Layer opacity={colour * 0.34} effects={[blur(80)]}>
          {LIGHTS.map(([x, y, c, dx, dy], i) => i === 2 || i === 3 ? null : (
            <Ellipse
              key={i}
              x={(x + dx * (g - 214)) * W - (i === 4 ? 130 : 280)}
              y={(y + dy * (g - 214)) * H - (i === 4 ? 100 : 190)}
              width={i === 4 ? 260 : 560}
              height={i === 4 ? 200 : 380}
              fill={radialGradient([c, `${c}00`])}
            />
          ))}
        </Layer>
      )}
      <Canvas
        width={W}
        height={H}
        effects={[blur(keys(g, [[197, 7], [199, 5], [203, 2.6], [210, 2.2]], lin))]}
        draw={(ctx) => drawDots(ctx as unknown as CanvasRenderingContext2D, g)}
      />

      <Layer id="whatif-line" x={keys(g, LEFT, lin)} y={CY} scale={keys(g, SCALE, lin)} motionBlur={{ samples: 16, shutter: g < 198 ? 0 : g < 237 ? 0.6 : 1 }}>
        <Layer y={-CY}>
          <Text font={UI} weight={800} size={size} color="#fff" x={xs[0]} y={top} {...word(195, 6, 4.5)}>
            But
          </Text>
          <Text font={UI} weight={400} size={size} color="#fff" x={xs[0] + butW * k} y={top} {...word(195, 6, 4.5)}>
            ,
          </Text>
          <Text font={UI} weight={400} size={size} color="#f4f4f4" x={xs[1]} y={top} {...word(206, 4, 8)}>
            what
          </Text>
          <Text font={UI} weight={400} size={size} color="#f4f4f4" x={xs[2]} y={top} {...word(210, 4, 8)}>
            if
          </Text>
          {g >= 213 && (
            <Layer x={xs[3] + glyph / 2} y={CY} scale={ramp(g, 213, 216, 0.7, 1)} {...word(213, 4, 6)}>
              <Layer x={-glyph / 2} y={-glyph / 2}>
                <AppGlyph size={glyph} />
              </Layer>
            </Layer>
          )}
        </Layer>
      </Layer>
    </Layer>
  );
};

// Shot 08 (frames 240-342): "...had Save Reminders?" under the post, close on its save button. A colour sweep runs
// through "Save Reminders?", the camera drifts right and pushes in on the button, the button is pressed (it shrinks,
// fills, and a grey ring spreads and fades), two bubbles lead down to the Reminder sheet, which pops out of them;
// the camera pulls back to show it whole, its toggle turns on, Apply is tapped, and the sheet collapses back into
// the button. Positions are the post's world pixels (the post at 0, 0); the camera keys were measured on the
// reference.

import React from 'react';
import { interpolateColors, useCurrentFrame } from 'remotion';
import { Ellipse, Layer, Rect, Text, blur, dropShadow } from '@kinetographdev/core';
import { measureText } from '@kinetographdev/core/layout-utils';
import { Cam, PAPER, ReminderMark, UI, easeOut, keys, ramp } from '../lib.js';
import { POST, PostCard } from '../post.js';
import { NightPicture, ReminderSheet, spline } from './c-ui.js';

const F0 = 240;
const MARK = { x: POST.width - 30, y: POST.actionsY(POST.imageHeight) }; // the save button's centre

// camera: [frame, x, y, zoom]
const CAM: [number, number, number, number][] = [
  [240, 334.7, 472.3, 3.0],
  [245, 360, 472.3, 3.0],
  [262, 394.7, 472.3, 3.1],
  [274, 411.4, 464.9, 3.5],
  [278, 420.3, 458.4, 3.9],
  [281, 430.9, 450.9, 4.5],
  [283, 436.3, 447.9, 4.9],
  [289, 442.7, 443.8, 5.5],
  [293, 444.4, 443.5, 5.6],
  [299, 445.5, 442.5, 5.4],
  [303, 447.6, 446.6, 5.4],
  [306, 450, 450, 5.25],
  [309, 460.7, 463.3, 4.6],
  [312, 469.8, 479.9, 4.25],
  [315, 479.2, 492.4, 3.7],
  [320, 485.4, 501, 3.5],
  [337, 487.5, 503.2, 3.47],
  [342, 470, 490, 3.6],
];
const camAt = (f: number, i: 1 | 2 | 3) => spline(f, CAM.map((k) => [k[0], k[i]] as [number, number]));

// the line under the post: regular, then "Save Reminders" bold, then "?"; right edge just left of the button
const SIZE = 15.5;
const HEAD = 'But, what if Instagram had ';
const BOLD = 'Save Reminders';
const LINE_RIGHT = 411;
const LINE_Y = 474 - SIZE * 0.6;

// the sweep: a band of orange then magenta running left to right through "Save Reminders?"
const AHEAD = '#8c8c92';
const DONE = '#3a3a3e';
function sweep(i: number, pos: number): string {
  const t = pos - i;
  if (t < 0) return AHEAD;
  if (t < 1.5) return interpolateColors(t, [0, 1.5], ['#f7a14a', '#f58a3a']);
  if (t < 7) return interpolateColors(t, [1.5, 4, 7], ['#f58a3a', '#e0389a', '#d22aa8']);
  if (t < 11) return interpolateColors(t, [7, 11], ['#d22aa8', DONE]);
  return DONE;
}

// the sheet's place in the world (its top left) and scale
const SHEET_AT = { x: 465.4, y: 472, k: 1 / 3.5 };

export const SaveReminders: React.FC = () => {
  const f = useCurrentFrame() + F0;

  const headW = measureText({ text: HEAD, fontFamily: UI, fontSize: SIZE, fontWeight: '400' }).width;
  const boldW = measureText({ text: BOLD, fontFamily: UI, fontSize: SIZE, fontWeight: '700' }).width;
  const qW = measureText({ text: '?', fontFamily: UI, fontSize: SIZE, fontWeight: '400' }).width;
  const x0 = LINE_RIGHT - headW - boldW - qW;
  const pos = keys(f, [[236, 5.5], [240, 7.5], [262, 19.5], [272, 30]], (t) => t);

  // the press: the button shrinks and fills at 281, springs back by 289; the grey ring spreads and fades
  const pressed = f >= 281;
  // the reference's button is a fifth bigger than the post's own one
  const markScale = keys(f, [[279, 1.22], [281.5, 0.75], [284, 0.85], [288, 1.3], [292, 1.22]], easeOut);
  const ring = ramp(f, 281, 300, 0, 1, (t) => 1 - (1 - t) * (1 - t));
  const ringD = 16 + 58 * ring;
  const ringShade = Math.round(keys(f, [[283, 120], [287, 168], [290, 200], [300, 222]], (t) => t));
  const ringOpacity = f < 281 ? 0 : ramp(f, 296, 302, 1, 0);
  // from 286 a paler disc opens round the button inside the grey one, so the grey reads as a ring
  const hole = ramp(f, 285, 292, 0, 1, easeOut);
  const holeD = ringD * 0.5 * hole;
  const holeShade = Math.round(ringShade + (242 - ringShade) * 0.55);
  // the disc is centred on the bookmark's body (the badge pokes out up and right)
  const RX = MARK.x - 0.2;
  const RY = MARK.y + 0.4;
  // the camera's blur: the reference keeps the press sharp while it zooms in on it
  const shutter = keys(f, [[240, 1.4], [279, 1.4], [283, 0.35], [300, 0.35], [306, 1.4]], (t) => t);

  // bubbles, then the sheet popping out of them (scale from its top left corner, sliding in from down right)
  const bubA = ramp(f, 297, 301, 0, 1, easeOut);
  const bubB = ramp(f, 300, 304, 0, 1, easeOut);
  const pop = ramp(f, 299, 305, 0, 1, easeOut);
  // and back into the button at the end
  const out = ramp(f, 337, 342, 0, 1, (t) => t * t);
  const sheetScale = SHEET_AT.k * (0.55 + 0.45 * pop) * (1 - 0.85 * out);
  const sheetX = SHEET_AT.x + 15 * (1 - pop) - 20 * out;
  const sheetY = SHEET_AT.y + 19 * (1 - pop) - 45 * out;
  const toggle = ramp(f, 322, 326, 0, 1);
  const ripple = ramp(f, 330, 341, 0, 1, (t) => t);
  const bubbleShadow = [dropShadow({ y: 1, blur: 1.5, color: '#00000020' })];

  return (
    <Layer>
      <Rect width={1080} height={810} fill={PAPER} />
      <Cam id="save-cam" x={camAt(f, 1)} y={camAt(f, 2)} zoom={camAt(f, 3)} blur={shutter}>
        <PostCard
          image={<NightPicture width={POST.width} height={POST.imageHeight} />}
          save={pressed ? 'reminderFilled' : 'reminder'}
          saveScale={markScale}
          headerOpacity={0}
          likes=""
          comments=""
          reposts=""
        />
        {/* the press ring, under the button */}
        {ringOpacity > 0 && (
          <Layer opacity={ringOpacity}>
            <Ellipse x={RX - ringD / 2} y={RY - ringD / 2} width={ringD} height={ringD} fill={`rgb(${ringShade},${ringShade},${ringShade})`} />
            {holeD > 0.5 && (
              <Ellipse
                x={RX - holeD / 2}
                y={RY - holeD / 2}
                width={holeD}
                height={holeD}
                fill={`rgb(${holeShade},${holeShade},${holeShade})`}
                effects={[blur(1)]}
              />
            )}
          </Layer>
        )}
        {ringOpacity > 0 && (
          // the button again, over its ring
          <Layer x={MARK.x + 1} y={MARK.y + 1} scale={markScale}>
            <Layer x={-13} y={-13}>
              <ReminderMark size={26} filled />
            </Layer>
          </Layer>
        )}
        <Text font={UI} weight={400} size={SIZE} color="#5c5c62" x={x0} y={LINE_Y}>
          {HEAD}
        </Text>
        <Text
          font={UI}
          weight={700}
          size={SIZE}
          color={DONE}
          x={x0 + headW}
          y={LINE_Y}
          chars={[...BOLD].map((_, i) => ({ color: sweep(i, pos) }))}
        >
          {BOLD}
        </Text>
        <Text font={UI} weight={400} size={SIZE} color={sweep(BOLD.length, pos)} x={x0 + headW + boldW} y={LINE_Y}>
          ?
        </Text>
        {bubA > 0 && out < 1 && (
          <Ellipse x={468 - 7.6 * bubA} y={458.1 - 7.6 * bubA} width={15.2 * bubA} height={15.2 * bubA} fill="#fff" effects={bubbleShadow} opacity={1 - out} />
        )}
        {bubB > 0 && out < 1 && (
          // the second bubble sits on the sheet's top edge, half under it, so the two read as one shape
          <Ellipse x={476.5 - 8.8 * bubB} y={472.6 - 8.8 * bubB} width={17.6 * bubB} height={17.6 * bubB} fill="#fff" effects={bubbleShadow} opacity={1 - out} />
        )}
        {pop > 0 && out < 1 && (
          <Layer x={sheetX} y={sheetY} scale={sheetScale} opacity={Math.min(1, pop * 2.5)} effects={out > 0 ? [blur(out * 40)] : undefined}>
            <ReminderSheet toggle={toggle} ripple={ripple} />
          </Layer>
        )}
      </Cam>
    </Layer>
  );
};

// Shot 09 (frames 343-372): the filled save button flies up out of shot 08 to fill the frame and bounces like a
// character, rocking side to side over its shadow, while "And done..!" settles beside it; the camera drifts up
// and then whips everything off to the left. Positions are screen pixels at frame 353, measured on the reference.

import React from 'react';
import { interpolateColors, useCurrentFrame } from 'remotion';
import { Ellipse, Layer, Rect, Text, blur } from '@kinetographdev/core';
import { measureText } from '@kinetographdev/core/layout-utils';
import { PAPER, ReminderMark, TEXT, UI, easeOut, keys, ramp } from '../lib.js';
import { spline } from './c-ui.js';

const F0 = 342;
const FLOOR = { x: 324, y: 616 };
const MARK = 350; // the icon's 24-unit box, in px: its body is 190 wide and 255 tall
const HALF_BODY = 128;
const WORDS = { x: 508, y: 462, size: 84 };

// the scene drifts up as the camera follows, then is whipped off to the left
const DY: [number, number][] = [[345, -114], [347, -63], [349, -27], [351, -9], [353, 0], [356, 10], [359, 18], [362, 26], [365, 32], [372, 44]];
const DX: [number, number][] = [[345, 0], [347, 13], [349, 5], [351, 0], [356, -3], [359, -28], [362, -98], [365, -246], [368, -540], [372, -1000]];
const ROT: [number, number][] = [[345, 0], [347, 12], [349, 8], [351, -12], [353, 0], [356, -10], [359, 0], [362, 18], [365, 10], [372, 6]];
const SWAY: [number, number][] = [[345, 364], [347, 375], [349, 350], [351, 335], [353, 331], [356, 327], [359, 325]];

export const AndDone: React.FC = () => {
  const f = useCurrentFrame() + F0;
  const shown = f >= 343; // frame 342 is still shot 08's

  const dx = spline(f, DX);
  const dy = spline(f, DY);
  // the bottom of the icon's body above the floor: a hop every 12.5 frames, landing at 357
  const hop = 20 + 115 * Math.abs(Math.sin((Math.PI * (f - 344.5)) / 12.5));
  const land = keys(f, [[356, 1], [357.5, 0.95], [360, 1]], easeOut);

  // the way in: out of shot 08's button (small, up left) to full size
  const inT = ramp(f, 341.5, 345, 0, 1, (t) => t);
  const restX = keys(f, SWAY);
  const restY = FLOOR.y - hop - HALF_BODY;
  const iconX = 397 + (restX - 397) * inT;
  const iconY = 189 + (restY + dy - 189) * inT;
  const iconScale = (0.19 + 0.81 * inT) * land;

  const andW = measureText({ text: 'And ', fontFamily: UI, fontSize: WORDS.size, fontWeight: '800' }).width;
  const and = ramp(f, 346, 349, 0, 1);
  const done = ramp(f, 348, 351, 0, 1);
  const grey = (t: number) => interpolateColors(t, [0, 1], ['#a8a8ac', TEXT]);
  const shadowW = 340 - 1.15 * hop;

  return (
    <Layer>
      <Rect width={1080} height={810} fill={PAPER} opacity={shown ? 1 : 0} />
      {/* an explicit id: on the sub-frames before 343 shot 08 is still in the tree and would shift an automatic one */}
      <Layer id="s09-scene" motionBlur={{ samples: 16, shutter: f < 361 ? 0.6 : 1.2 }} opacity={f >= 342.5 ? 1 : 0}>
        <Layer x={dx}>
          <Layer y={dy} opacity={ramp(f, 343, 345, 0, 1)}>
            <Ellipse
              x={FLOOR.x - shadowW / 2}
              y={FLOOR.y - 13}
              width={shadowW}
              height={26}
              fill="#000"
              opacity={0.16 + 0.1 * (1 - hop / 135)}
              effects={[blur(4)]}
            />
          </Layer>
          <Layer x={iconX} y={iconY} rotation={keys(f, ROT)} scale={iconScale}>
            <Layer x={-MARK / 2} y={-MARK / 2}>
              <ReminderMark size={MARK} filled color="#050505" badgeBg="#fff" />
            </Layer>
          </Layer>
          <Layer y={dy}>
            {and > 0 && (
              <Text
                font={UI}
                weight={800}
                size={WORDS.size}
                color={grey(and)}
                x={WORDS.x}
                y={WORDS.y - 8 * (1 - and)}
                opacity={0.4 + 0.6 * and}
                effects={and < 1 ? [blur(4 * (1 - and))] : undefined}
              >
                And
              </Text>
            )}
            {done > 0 && (
              <Text
                font={UI}
                weight={800}
                size={WORDS.size}
                color={grey(done)}
                x={WORDS.x + andW}
                y={WORDS.y + 8 * (1 - done)}
                opacity={0.4 + 0.6 * done}
                effects={done < 1 ? [blur(4 * (1 - done))] : undefined}
              >
                done..!
              </Text>
            )}
          </Layer>
        </Layer>
      </Layer>
    </Layer>
  );
};

// Shot 10 (frames 372-412): "Instagram's gonna [notification] you". The words slide in from the right and settle,
// a pink-tinted, blurred notification drops into the gap, clears, and a second card rises tilted behind it; "you"
// follows; then the whole line is whipped up out of frame. Screen pixels, measured on the reference.

import React from 'react';
import { interpolateColors, useCurrentFrame } from 'remotion';
import { Layer, Rect, Text, blur } from '@kinetographdev/core';
import { measureText } from '@kinetographdev/core/layout-utils';
import { PAPER, TEXT, UI, keys, ramp } from '../lib.js';
import { NOTICE, NoticeStack, spline } from './c-ui.js';

const F0 = 372;
const CENTER_Y = 394;
const PILL = 0.32; // the notification's scale here (its design size is the close-up's in shot 11)

const measure = (text: string, size: number) => measureText({ text, fontFamily: UI, fontSize: size, fontWeight: '500' }).width;

export const Gonna: React.FC = () => {
  const f = useCurrentFrame() + F0;
  // the reference's "Instagram’s" is 221 px wide
  const size = (40 * 221) / measure('Instagram’s', 40);
  const top = CENTER_Y - size * 0.6;

  const x0 = spline(f, [[372, 284], [374, 211], [377, 148], [380, 121], [383, 113]]);
  const gonnaFinal = measure('Instagram’s ', size);
  const gonnaX = x0 + spline(f, [[377, 292], [380, 262], [383, 254], [390, 241], [395, gonnaFinal]]);
  const gonna = ramp(f, 376, 383, 0, 1);
  const pillFinal = gonnaFinal + measure('gonna', size) + 24;
  const pillX = x0 + spline(f, [[383, pillFinal + 19], [385, pillFinal + 14], [387, pillFinal + 6], [390, pillFinal]]);
  const pill = ramp(f, 382, 383.5, 0, 1);
  const youX = x0 + pillFinal + NOTICE.width * PILL + 11 + spline(f, [[385, 62], [387, 35], [390, 16], [395, 0]]);
  const you = ramp(f, 384.5, 390, 0, 1);
  const dy = spline(f, [[395, 0], [400, -6], [404, -29], [406, -52], [408, -81], [409, -110], [411, -227], [413, -520]]);
  const entry = ramp(f, 372, 377, 1, 0);

  return (
    <Layer>
      <Rect width={1080} height={810} fill={PAPER} />
      <Layer id="s10-line" y={dy} motionBlur={{ samples: 16, shutter: f < 409 ? 0.4 : 1.2 }}>
        <Text font={UI} weight={500} size={size} color={TEXT} x={x0} y={top} effects={entry > 0 ? [blur(5 * entry)] : undefined}>
          Instagram’s
        </Text>
        {gonna > 0 && (
          <Text
            font={UI}
            weight={500}
            size={size}
            color={interpolateColors(gonna, [0, 1], ['#b4b4b8', TEXT])}
            x={gonnaX}
            y={top}
            opacity={0.3 + 0.7 * gonna}
            effects={gonna < 1 ? [blur(6 * (1 - gonna))] : undefined}
          >
            gonna
          </Text>
        )}
        {pill > 0 && (
          <Layer
            x={pillX}
            y={CENTER_Y + 6 - (NOTICE.height * PILL) / 2}
            scale={PILL}
            opacity={pill}
            effects={f < 388 ? [blur(ramp(f, 383, 388, 10, 0))] : undefined}
          >
            <NoticeStack
              backY={keys(f, [[386, 0], [387, -112], [390, -200], [395, -184]], (t) => t)}
              backRotation={3}
              backOpacity={ramp(f, 386, 388, 0, 1)}
              tint={ramp(f, 383, 394, 0.9, 0)}
              backTint={ramp(f, 383, 394, 0.9, 0.12)}
              backDim={0.12}
            />
          </Layer>
        )}
        {you > 0 && (
          <Text
            font={UI}
            weight={500}
            size={size}
            color={interpolateColors(you, [0, 1], ['#b4b4b8', TEXT])}
            x={youX}
            y={top}
            opacity={0.25 + 0.75 * you}
          >
            you
          </Text>
        )}
      </Layer>
    </Layer>
  );
};

// Shot 11 (frames 412-452): close on the notification. The two cards rise in from below, the back one tilted and
// paler, the "a" of "gonna" on the left; they drift up, the stack closing, and are whipped up out of frame. Screen
// pixels, the cards at their design size, measured on the reference.

import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Layer, Rect, Text, blur } from '@kinetographdev/core';
import { measureText } from '@kinetographdev/core/layout-utils';
import { PAPER, TEXT, UI, ramp } from '../lib.js';
import { NoticeCard, spline } from './c-ui.js';

const F0 = 412;
const FRONT_X = 100;
const WORD = 157; // "gonna" at the close-up's scale: its "a" has an 86 px x-height

const FRONT_Y: [number, number][] = [
  [412, 1100], [414, 860], [416, 621], [418, 526], [420, 472], [423, 410], [427, 370], [433, 345], [440, 316],
  [445, 238], [448, 86], [451, -250], [453, -560],
];
const BACK_Y: [number, number][] = [
  [412, 715], [414, 500], [416, 378], [418, 310], [420, 256], [423, 216], [427, 184], [433, 175], [440, 148],
  [445, 121], [448, -40], [451, -380], [453, -700],
];

export const Notice: React.FC = () => {
  const f = useCurrentFrame() + F0;
  const front = spline(f, FRONT_Y);
  const back = spline(f, BACK_Y);
  const gonnaW = measureText({ text: 'gonna', fontFamily: UI, fontSize: WORD, fontWeight: '500' }).width;

  return (
    <Layer>
      <Rect width={1080} height={810} fill={PAPER} />
      <Layer id="s11-stack" motionBlur={{ samples: 16, shutter: f < 415 || f > 446 ? 1 : 0.3 }}>
        <Layer x={spline(f, [[414, 162], [416, 148]])} y={back} rotation={spline(f, [[414, 7], [416, 5], [420, 4], [433, 3], [445, 2]])}
          // the back card falls out of focus as the front one settles
          effects={[blur(ramp(f, 421, 440, 0.6, 6.5, (t) => t * t))]}
        >
          <NoticeCard dim={ramp(f, 416, 423, 0, 0.15)} now={false} />
        </Layer>
        <Layer y={front}>
          <Text font={UI} weight={500} size={WORD} color={TEXT} x={54 - gonnaW} y={130 - WORD * 0.7}>
            gonna
          </Text>
          <Layer x={FRONT_X}>
            <NoticeCard now={false} />
          </Layer>
        </Layer>
      </Layer>
    </Layer>
  );
};

